// Fig. 2.5: fig02_05.c (Compiled as portable C++17 via <cstdio>)
// Addition program.
#include <cstdio>

// function main begins program execution
int main(void)
{
   int integer1; // first number to be entered by user
   int integer2; // second number to be entered by user

   std::printf("Enter first integer\n"); // prompt
   std::scanf("%d", &integer1); // read an integer

   std::printf("Enter second integer\n"); // prompt
   std::scanf("%d", &integer2); // read an integer

   int sum; // variable in which sum will be stored
   sum = integer1 + integer2; // assign total to sum

   std::printf("Sum is %d\n", sum); // print sum
   return 0;
} // end function main
